    static func describe(_ code: String) -> String {
        if let text = descriptions[code] { return L10n.text(text) }
        return technicalDetail(code) == nil ? L10n.text(code) : L10n.text("This item has additional information. Expand Details to read it.")
    }

    static func technicalDetail(_ code: String) -> String? {
        guard descriptions[code] == nil, L10n.catalog(.english)[code] == nil else { return nil }
        return code
    }
